let editTaskId=null,editMemberId=null;
function syncMemberOptions(){const previous=$('#person').value;people.splice(0,people.length,...members.map(m=>m.name));const options=members.map((m,i)=>m.active&&!m.legacy?`<option value="${i}">${esc(m.name)} · ${esc(m.role)}</option>`:'').join('');$('#person').innerHTML=options;$('#person').value=members[Number(previous)]?.active?previous:String(members.findIndex(m=>m.active&&!m.legacy));$('#taskOwner').innerHTML=$('#deliveryOwner').innerHTML=members.map((m,i)=>canAssignOwner(i)?`<option value="${i}">${esc(m.name)} · ${esc(m.role)}</option>`:'').join('')}
function statusControl(t){return canEdit(t)?`<select class="status-select ${statusClass(t.status)}" data-status-task="${t.id}" aria-label="وضعیت ${esc(t.title)}">${['تعریف‌شده','در حال انجام','متوقف‌شده','انجام‌شده'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select>`:badge(t)}
function updateStatus(id,status){const t=tasks.find(t=>t.id===id);if(!t||!canEdit(t)){render();return toast('فقط مسئول کار یا مدیریت می‌تواند وضعیت را تغییر دهد')}if(!['تعریف‌شده','در حال انجام','متوقف‌شده','انجام‌شده'].includes(status))return;if(status===t.status)return;if(status==='انجام‌شده'){complete(t);return}let reason='';if(status==='متوقف‌شده'){reason=prompt('دلیل توقف کار چیست؟');if(!reason?.trim()){render();return}}t.status=status;t.completed=null;t.reason=reason;if(status==='تعریف‌شده')t.progress=0;if(t.progress===100)t.progress=0;logChange(t,'وضعیت به «'+status+'» تغییر کرد.'+(reason?' دلیل: '+reason:''));save();toast('وضعیت کار تغییر کرد')}
function openTaskEdit(t){if(!canAdminTask(t))return;editTaskId=t.id;$('#details').close();$('#taskForm').reset();$('#taskForm h2').textContent='ویرایش کار';$('#taskOwner').disabled=false;for(const name of ['title','description','owner','priority','start','due','status','reason'])$('#taskForm').elements[name].value=t[name]??'';if(members[t.owner]?.legacy){$('#taskOwner').insertAdjacentHTML('beforeend',`<option value="${t.owner}">${esc(people[t.owner])}</option>`);$('#taskOwner').value=t.owner}$('#taskForm').elements.progress.value=progress(t);$('#editor').showModal()}
function renderMembers(){if(!manager())return;$('#workspace').innerHTML=`<div class="members-heading"><p>تعریف اعضا، سمت و سطح دسترسی در نمونه</p><button class="primary" id="newMember">＋ افزودن عضو</button></div><div class="formula">این بخش اعضای پروژه را در نمونه تعریف می‌کند. حساب ورود یا دعوت‌نامه ایجاد نمی‌شود؛ دسترسی اینترنتی واقعی پس از اتصال ورود امن فعال می‌شود.<br>مدیر پروژه: دسترسی به همه اعضا و کارها. سرپرست: مدیریت دسترسی کامل مدیریتی. دسترسی عضو: مشاهده همه کارها و تغییر وضعیت فقط کارهای محول‌شده به خودش.</div>${panel('اعضای پروژه دارایی',`<div class="table-wrap"><table><thead><tr><th>نام و نام خانوادگی</th><th>سمت</th><th>سطح دسترسی</th><th>وضعیت در نمونه</th><th>ورود واقعی</th><th></th></tr></thead><tbody>${members.map((m,i)=>m.legacy?'':`<tr><td>${person(i)}</td><td>${esc(m.role)}</td><td>${managementLabel(m)}</td><td><span class="pill ${m.active?'done':'stopped'}">${m.active?'فعال':'غیرفعال'}</span></td><td class="muted">متصل نشده</td><td>${canManageMember(i)?`<button class="table-action" data-edit-member="${i}">ویرایش عضو</button>`:'<span class="muted">اختیار مدیر پروژه</span>'}</td></tr>`).join('')}</tbody></table></div>`)}<p class="hint">کارهای قدیمی با عنوان «نمونه قبلی» حفظ شده‌اند و در گزارش افراد واقعی محاسبه نمی‌شوند.</p>`;$('#newMember').onclick=()=>openMember();$('#workspace').querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>openMember(Number(b.dataset.editMember)))}
function openMember(i=null){if(!manager()||(i!==null&&!canManageMember(i)))return;editMemberId=i;const m=i===null?null:members[i];$('#memberForm').reset();$('#memberForm').elements.access.innerHTML='<option value="member">عضو · کارهای خود</option><option value="supervisor">سرپرست · دسترسی کامل مدیریتی</option>'+(isDirector()?'<option value="director">مدیر پروژه · همه اعضا</option>':'');$('#memberTitle').textContent=m?'ویرایش عضو':'افزودن عضو پروژه';if(m)for(const k of ['name','role','email','access'])$('#memberForm').elements[k].value=m[k]||'';$('#memberForm').elements.active.checked=m?m.active:true;$('#memberEditor').showModal()}
document.body.insertAdjacentHTML('beforeend',`<dialog id="memberEditor"><form id="memberForm"><div class="dialog-head"><h2 id="memberTitle">افزودن عضو پروژه</h2><button class="close" type="button" id="closeMember">×</button></div><label>نام و نام خانوادگی<input name="name" required maxlength="100"></label><label>سمت<input name="role" required maxlength="100" placeholder="مثلاً کارشناس اجرا"></label><label>ایمیل برای اتصال حساب در آینده (اختیاری)<input name="email" type="email" dir="ltr" maxlength="200"></label><label>سطح دسترسی<select name="access"><option value="member">عضو · تغییر وضعیت کارهای خود</option><option value="supervisor">سرپرست · دسترسی کامل مدیریتی</option><option value="director">مدیر پروژه · همه اعضا</option></select></label><label class="checkbox-label"><input type="checkbox" name="active" checked>فعال در نمونه</label><p class="hint">ثبت این فرم دعوت‌نامه ارسال نمی‌کند و اجازه ورود واقعی نمی‌دهد.</p><div class="form-footer"><button type="button" id="cancelMember" class="secondary">انصراف</button><button class="primary">ذخیره عضو</button></div></form></dialog>`);
$('#closeMember').onclick=$('#cancelMember').onclick=()=>$('#memberEditor').close();$('#memberForm').onsubmit=e=>{e.preventDefault();if(!manager())return;const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();d.role=d.role.trim();d.email=d.email.trim();d.active=$('#memberForm').elements.active.checked;if(!d.name||!d.role)return;if(!['member','supervisor','director'].includes(d.access))return;if(!isDirector()&&(d.access==='director'||(editMemberId!==null&&!canManageMember(editMemberId))))return toast('تغییر مدیر پروژه در اختیار خود مدیر پروژه است');if(members.some((m,i)=>!m.legacy&&i!==editMemberId&&m.name===d.name))return toast('عضوی با این نام تعریف شده است');if(editMemberId!==null&&members[editMemberId].access==='director'&&members[editMemberId].active&&(!d.active||d.access!=='director')&&!members.some((m,i)=>i!==editMemberId&&m.active&&m.access==='director'))return toast('حداقل یک مدیر پروژه فعال باید باقی بماند');if(editMemberId===null)members.push({...d,id:crypto.randomUUID(),legacy:false});else Object.assign(members[editMemberId],d);localStorage.setItem('daraei-members-v1',JSON.stringify(members));$('#memberEditor').close();syncMemberOptions();render();toast('عضو در نمونه ذخیره شد')};
$('#stats').onclick=e=>{const b=e.target.closest('[data-stat]');if(!b)return;query=ownerFilter=statusFilter='';if(b.dataset.stat==='all')view='all';if(b.dataset.stat==='done')view='done';if(b.dataset.stat==='progress'){view='active';statusFilter='در حال انجام'}if(b.dataset.stat==='late'){view='active';statusFilter='late'}render()};$('#workspace').onchange=e=>{if(e.target.matches('[data-status-task]'))updateStatus(e.target.dataset.statusTask,e.target.value)};
